func:
var saved = flow.get('config', 'persistent');
var defaults = {
    socOnThreshold: 70,
    tempOnThreshold: 20,
    voltageOnThreshold: 53.5,
    socOffThreshold: 65,
    timeOnHour: 9,
    timeOffHour: 19,
    onDelay: 60,
    offDelay: 60,
    targetTemp: 24,
    mode: 'cool',
    fanSpeed: 'auto'
};
var config = Object.assign({}, defaults, saved || {});
flow.set('config', config);
flow.set('config', config, 'persistent');
if (!flow.get('acState')) {
    flow.set('acState', {power:false,lastChange:Date.now(),conditionsMetSince:null,conditionsNotMetSince:null,manualMode:false});
}
flow.set('currentValues', {soc:0,batteryVoltage:0,batteryState:'Unbekannt',batterySystemState:'Unbekannt',batterySystemStateNum:-1,temperature:0,tempReceived:false,outsideTemp:0,outsideTempReceived:false});
node.status({fill:'green',shape:'dot',text:'Config geladen'});
msg.payload = config;
return msg;

var values = flow.get('currentValues') || {soc:0,batteryVoltage:0,batteryState:'Unbekannt',batterySystemState:'Unbekannt',batterySystemStateNum:-1,temperature:0,tempReceived:false,outsideTemp:0,outsideTempReceived:false};

var path = msg.path || msg.topic || '';

if (path.indexOf('Battery SOC') !== -1) {
    values.soc = (msg.payload !== null && msg.payload !== undefined) ? Number(msg.payload) : 0;
}
else if (path.indexOf('Battery State') !== -1) {
    var sysState = Number(msg.payload);
    var sysNames = {0:'Idle',1:'Laden',2:'Entladen'};
    values.batterySystemState    = sysNames[sysState] || ('State:' + sysState);
    values.batterySystemStateNum = sysState;
}
else if (path.indexOf('Battery Voltage') !== -1) {
    values.batteryVoltage = (msg.payload !== null && msg.payload !== undefined) ? Number(msg.payload) : 0;
    var v = values.batteryVoltage;
    if      (v >= 56.0) { values.batteryState = 'Absorption'; }
    else if (v >= 53.5) { values.batteryState = 'Float';      }
    else if (v >  0)    { values.batteryState = 'Bulk';       }
    else                { values.batteryState = 'Unbekannt';  }
}
else if (path.indexOf('Ruuvi Innen') !== -1) {
    if (msg.payload !== null && msg.payload !== undefined) {
        values.temperature  = Number(msg.payload);
        values.tempReceived = true;
    }
}
else if (path.indexOf('Ruuvi Außen') !== -1) {
    if (msg.payload !== null && msg.payload !== undefined) {
        values.outsideTemp         = Number(msg.payload);
        values.outsideTempReceived = true;
    }
}

flow.set('currentValues', values);

var inStr   = values.tempReceived        ? values.temperature.toFixed(1) + 'C' : '---';
var outStr  = values.outsideTempReceived ? values.outsideTemp.toFixed(1) + 'C' : '---';
var voltStr = values.batteryVoltage > 0  ? values.batteryVoltage.toFixed(2) + 'V' : '?V';
node.status({text:'SOC:' + Math.round(values.soc||0) + '% ' + voltStr + ' ' + (values.batteryState||'?') + ' In:' + inStr + ' Out:' + outStr});

return {payload: values};

var values = msg.payload || {};
var state  = flow.get('acState')  || {};
var config = flow.get('config')   || {};

var soc     = (values.soc !== undefined)            ? values.soc            : 0;
var temp    = (values.temperature !== undefined)    ? values.temperature    : 0;
var voltage = (values.batteryVoltage !== undefined) ? values.batteryVoltage : 0;
var battSt  = values.batteryState || '?';
var outside = values.outsideTempReceived ? values.outsideTemp : null;

var socMsg  = {payload: Math.round(soc)};
var tempMsg = {payload: parseFloat(temp.toFixed(1))};

var battDisplay = voltage > 0 ? battSt + ' (' + voltage.toFixed(2) + 'V)' : battSt;
var battStateMsg   = {payload: battDisplay};
var klimaStatusMsg = {payload: state.power ? 'EIN' : 'AUS'};
var modeTextMsg    = {payload: state.manualMode ? 'MANUELL' : 'AUTOMATIK'};

var outsideDisplay;
if (outside !== null) {
    var hint = '';
    if (outside < 20)      hint = ' → Lüften';
    else if (outside > 30) hint = ' → Früh kühlen';
    outsideDisplay = outside.toFixed(1) + '°C' + hint;
} else {
    outsideDisplay = 'kein Sensor';
}
var outsideTempMsg = {payload: outsideDisplay};

var tempOnThr = config.tempOnThreshold || 22;
var effectiveTempOn = tempOnThr;
if (outside !== null) {
    if (outside < 20)      effectiveTempOn = tempOnThr + 3;
    else if (outside > 30) effectiveTempOn = Math.max(tempOnThr - 2, 18);
}

var statusText = '';
var onHour    = config.timeOnHour  !== undefined ? config.timeOnHour  : 6;
var offHour   = config.timeOffHour !== undefined ? config.timeOffHour : 21;
var socOnThr  = config.socOnThreshold    || 70;
var voltOnThr = config.voltageOnThreshold || 53.5;

if (state.manualMode) {
    statusText = state.power ? 'Manuell eingeschaltet' : 'Manuell ausgeschaltet';
} else if (state.power) {
    statusText = 'Läuft | SOC ' + Math.round(soc) + '% | ' + battDisplay;
} else {
    var hour = new Date().getHours();
    if (hour < onHour || hour >= offHour) {
        statusText = 'Ruhezeit (' + onHour + ':00–' + offHour + ':00)';
    } else if (soc < socOnThr) {
        statusText = 'Warte: SOC ' + Math.round(soc) + '% < ' + socOnThr + '%';
    } else if (!values.tempReceived) {
        statusText = 'Warte: Kein Innen-Sensor!';
    } else if (temp < effectiveTempOn) {
        var effStr = (effectiveTempOn !== tempOnThr) ? ' (eff. ' + effectiveTempOn + 'C, Außen: ' + (outside !== null ? outside.toFixed(1) : '?') + 'C)' : '';
        statusText = 'Warte: Innen ' + temp.toFixed(1) + 'C < ' + effectiveTempOn + 'C' + effStr;
    } else if (voltage < voltOnThr) {
        statusText = 'Warte: ' + voltage.toFixed(2) + 'V < ' + voltOnThr + 'V (Bulk)';
    } else if (values.batterySystemStateNum === 2) {
        statusText = 'Warte: Kein PV – Batterie entlädt';
    } else {
        statusText = 'Bedingungen erfüllt – starte bald...';
    }
}
var statusMsg = {payload: statusText};

return [socMsg, tempMsg, battStateMsg, klimaStatusMsg, modeTextMsg, statusMsg, outsideTempMsg];

var config = flow.get('config') || {};
var values = flow.get('currentValues') || {};
var state  = flow.get('acState') || {};

var now  = Date.now();
var hour = new Date().getHours();

var soc     = values.soc || 0;
var temp    = (values.temperature !== undefined) ? values.temperature : 0;
var voltage = values.batteryVoltage || 0;
var outside = values.outsideTempReceived ? values.outsideTemp : null;

var onHour    = config.timeOnHour   !== undefined ? config.timeOnHour   : 6;
var offHour   = config.timeOffHour  !== undefined ? config.timeOffHour  : 21;
var socOffThr = config.socOffThreshold    || 65;
var socOnThr  = config.socOnThreshold     || 70;
var tempOnThr = config.tempOnThreshold    || 22;
var voltOnThr = config.voltageOnThreshold || 53.5;
var onDelay   = config.onDelay  || 120;
var offDelay  = config.offDelay || 60;

// Dynamische Einschwell-Temperatur basierend auf Außentemperatur
var effectiveTempOn = tempOnThr;
if (outside !== null) {
    if (outside < 20) {
        effectiveTempOn = tempOnThr + 3;  // Außen kühl: Lüften reicht
    } else if (outside > 30) {
        effectiveTempOn = Math.max(tempOnThr - 2, 18);  // Außen heiß: früher kühlen
    }
}

if (state.manualMode) {
    node.status({fill:'blue',shape:'dot',text:'Manuell: ' + (state.power ? 'EIN' : 'AUS')});
    return null;
}

var timeOK = (hour >= onHour && hour < offHour);
if (!timeOK) {
    if (state.power) {
        state.power = false;
        state.conditionsNotMetSince = null;
        flow.set('acState', state);
        node.status({fill:'grey',shape:'dot',text:'Ruhezeit'});
        return {payload: {action:'off',reason:'Außerhalb Betriebszeit'}};
    }
    node.status({fill:'grey',shape:'ring',text:'Ruhezeit (' + onHour + ':00–' + offHour + ':00)'});
    return null;
}

if (soc < socOffThr) {
    if (state.power) {
        if (!state.conditionsNotMetSince) {
            state.conditionsNotMetSince = now;
            flow.set('acState', state);
        }
        var waited = (now - state.conditionsNotMetSince) / 1000;
        if (waited >= offDelay) {
            state.power = false;
            state.conditionsNotMetSince = null;
            flow.set('acState', state);
            var r = 'SOC ' + Math.round(soc) + '% < ' + socOffThr + '%';
            node.status({fill:'red',shape:'dot',text:'AUS: ' + r});
            return {payload: {action:'off',reason:r}};
        }
        node.status({fill:'yellow',shape:'dot',text:'AUS in ' + Math.round(offDelay-waited) + 's'});
        return null;
    }
}

// stateOK: 0=Idle (Batterie voll) oder 1=Charging = PV vorhanden
// voltOK als Nachtschutz: nachts fällt Spannung unter 53.5V auch bei State 0
var socOK   = soc >= socOnThr;
var tempOK  = temp >= effectiveTempOn;
var voltOK  = voltage >= voltOnThr;
var stateOK = (values.batterySystemStateNum === 1 || values.batterySystemStateNum === 0);
var battOK  = voltOK && stateOK;
var allOK   = socOK && tempOK && battOK;

if (!state.power && allOK) {
    if (!state.conditionsMetSince) {
        state.conditionsMetSince = now;
        flow.set('acState', state);
    }
    var waited2 = (now - state.conditionsMetSince) / 1000;
    if (waited2 >= onDelay) {
        state.power = true;
        state.conditionsMetSince = null;
        state.conditionsNotMetSince = null;
        flow.set('acState', state);
        var r2 = 'SOC ' + Math.round(soc) + '% | ' + voltage.toFixed(2) + 'V | In:' + temp.toFixed(1) + 'C';
        node.status({fill:'green',shape:'dot',text:'EIN: ' + r2});
        return {payload: {action:'on',reason:r2}};
    }
    node.status({fill:'yellow',shape:'dot',text:'EIN in ' + Math.round(onDelay-waited2) + 's'});
    return null;
}

if (!allOK) {
    state.conditionsMetSince = null;
    flow.set('acState', state);
}

if (state.power) {
    state.conditionsNotMetSince = null;
    flow.set('acState', state);
    node.status({fill:'green',shape:'dot',text:'Läuft | ' + voltage.toFixed(2) + 'V | SOC ' + Math.round(soc) + '%'});
} else {
    var w = [];
    if (!socOK)   w.push('SOC<' + socOnThr + '%');
    if (!tempOK)  w.push('In:' + temp.toFixed(1) + '<' + effectiveTempOn + 'C');
    if (!voltOK)  w.push(voltage.toFixed(2) + 'V<' + voltOnThr + 'V');
    if (!stateOK) w.push('Entladen');
    node.status({fill:'grey',shape:'ring',text:'Warte: ' + w.join(' | ')});
}

return null;

var config = flow.get('config') || {};
var action = msg.payload.action;
var greeMsg = {topic: action};
if (action === 'on') {
    greeMsg.payload = {power:'on',mode:config.mode||'cool',temperature:config.targetTemp||24,fanSpeed:config.fanSpeed||'auto'};
    node.status({fill:'green',shape:'dot',text:'EIN: ' + (config.targetTemp||24) + 'C'});
} else if (action === 'off') {
    greeMsg.payload = {power: 'off'};
    node.status({fill:'red',shape:'dot',text:'AUS gesendet'});
}
return greeMsg;

var state = flow.get('acState') || {};
state.manualMode = msg.payload;
flow.set('acState', state);
if (!state.manualMode) {
    node.status({fill:'green',shape:'ring',text:'Automatik aktiv'});
} else {
    node.status({fill:'blue',shape:'dot',text:'Manuell aktiv'});
}
var values = flow.get('currentValues') || {};
return {payload: values};

var config = flow.get('config') || {};
var state  = flow.get('acState') || {};
var cmd    = msg.payload;
if (!state.manualMode) {
    node.status({fill:'yellow',shape:'ring',text:'Erst Manuell aktivieren!'});
    return null;
}
var greeMsg = {topic: cmd};
if (cmd === 'on') {
    state.power = true;
    flow.set('acState', state);
    greeMsg.payload = {power:'on',mode:config.mode||'cool',temperature:config.targetTemp||24,fanSpeed:config.fanSpeed||'auto'};
    node.status({fill:'green',shape:'dot',text:'Manuell EIN'});
} else if (cmd === 'off') {
    state.power = false;
    flow.set('acState', state);
    greeMsg.payload = {power: 'off'};
    node.status({fill:'red',shape:'dot',text:'Manuell AUS'});
}
var values = flow.get('currentValues') || {};
return [greeMsg, {payload: values}];

var c = flow.get('config') || {};
node.send([
    [{payload: c.targetTemp      || 24}],
    [{payload: c.tempOnThreshold || 22}],
    [{payload: c.timeOnHour      || 6}],
    [{payload: c.timeOffHour     || 21}],
    [{payload: c.socOnThreshold  || 70}],
    [{payload: c.socOffThreshold || 65}]
]);
return null;

var config = flow.get('config') || {};
var key   = msg.topic;
var value = Number(msg.payload);
if (key === 'socOffThreshold' && value >= (config.socOnThreshold || 70)) {
    node.status({fill:'red',shape:'dot',text:'Fehler: AUS-SOC (' + value + '%) muss < EIN-SOC (' + (config.socOnThreshold||70) + '%)'});
    return null;
}
if (key === 'socOnThreshold' && value <= (config.socOffThreshold || 65)) {
    node.status({fill:'red',shape:'dot',text:'Fehler: EIN-SOC (' + value + '%) muss > AUS-SOC (' + (config.socOffThreshold||65) + '%)'});
    return null;
}
if (key === 'timeOnHour' && value >= (config.timeOffHour || 21)) {
    node.status({fill:'red',shape:'dot',text:'Fehler: Von (' + value + 'h) muss < Bis (' + (config.timeOffHour||21) + 'h)'});
    return null;
}
if (key === 'timeOffHour' && value <= (config.timeOnHour || 6)) {
    node.status({fill:'red',shape:'dot',text:'Fehler: Bis (' + value + 'h) muss > Von (' + (config.timeOnHour||6) + 'h)'});
    return null;
}
config[key] = value;
flow.set('config', config);
flow.set('config', config, 'persistent');
node.status({fill:'green',shape:'dot',text: key + ' = ' + value + ' ✓'});
return null;

// Erkennt Wiederverbindung der Gree und triggert Resync
var now = Date.now();
var lastOutput = flow.get('lastGreeOutput') || 0;
var wasAlive   = flow.get('greeWasAlive') || false;

// Reconnect erkennen:
//   - lastOutput=0  → allererster Output ueberhaupt
//   - lastOutput >5min alt → war offline und ist jetzt wieder da
//   - wasAlive=false → war als nicht-lebend markiert
var ageMin = lastOutput > 0 ? (now - lastOutput)/1000/60 : 999;
var reconnect = (!wasAlive) || (ageMin > 5);

flow.set('lastGreeOutput', now);
flow.set('greeWasAlive', true);
flow.set('greeErrorCount', 0);

if (reconnect) {
    node.status({fill:'blue', shape:'dot',
        text: 'Reconnect erkannt -> Resync wird ausgeloest'});
    return {payload: 'resync'};
}

node.status({fill:'green', shape:'dot', text: new Date().toLocaleTimeString()});
return null;

var last = flow.get('lastGreeOutput') || 0;
var now  = Date.now();

// Erster Lauf nach Start: Timer initialisieren mit jetzt
// damit die 20-Min Frist auch laeuft wenn nie Verbindung kam
if (last === 0) {
    flow.set('lastGreeOutput', now);
    node.status({fill:'yellow', shape:'ring', text: 'Watchdog gestartet, warte auf Kontakt'});
    return null;
}

var age = (now - last) / 1000 / 60;  // Minuten

if (age > 20) {
    node.status({fill:'red', shape:'dot',
        text: 'Kein Output seit ' + Math.round(age) + 'min -> Neustart'});
    flow.set('lastGreeOutput', 0);  // Reset fuer naechsten Zyklus
    return {payload: 'watchdog-restart'};
}

node.status({fill:'green', shape:'dot',
    text: 'OK, letzter Output vor ' + Math.round(age) + 'min'});
return null;

// Resync nach Reconnect: sendet aktuellen gewuenschten Zustand an Klima
var config = flow.get('config') || {};
var state  = flow.get('acState') || {};

if (state.power) {
    // Soll-Zustand: EIN - vollstaendige Konfiguration neu senden
    var greeMsg = {
        topic: 'on',
        payload: {
            power:       'on',
            mode:        config.mode || 'cool',
            temperature: config.targetTemp || 24,
            fanSpeed:    config.fanSpeed || 'auto'
        }
    };
    node.status({fill:'green', shape:'dot',
        text: 'Resync EIN @ ' + (config.targetTemp||24) + 'C'});
    return greeMsg;
} else {
    // Soll-Zustand: AUS - explizit AUS senden um sicher zu sein
    node.status({fill:'red', shape:'dot', text: 'Resync AUS'});
    return {topic: 'off', payload: {power: 'off'}};
}
